\label{t:timese}
Let $T^*$ be any fixed regular tournament with $d\ge 1$ vertices. Then 
$${\bf E} [H({\cal R}(T^*))]\sim {\bf E} [H({\cal R}_0(T^*))]\sim e^{1/d} {\bf E}[ H({\cal T}(T^*))].$$

\label{t:paths}
Theorems~\ref{t:timese} and~\ref{t:coeff}  are both valid with $H$
and $g$ replaced by $H'$ and $g'$.

\label{con5}
 The limits $\lim_{d\to\infty} \rho_{\cal R}(R_d)$  and $\lim_{n\to\infty}
h(n)/g(n)$ are equal and have the approximate value 2.855958.

\label{formulae}
Let $T^*$ be any fixed  tournament with at least three vertices. Then
\begin{eqnarray}
{\bf E} [H({\cal T}(T^*))] &=& \nonumber\\
 &&\hspace{-2.5cm} \left(\frac{n!}{2^{n}}\right)^d\sum_{j_1,\ldots , j_d\ge
1} j_1^{-1}[x_1^{j_1}\cdots x_d^{j_d}] f(x_1,\ldots ,x_d)
\prod_{i=1}^d  \left( n-1\atop j_i-1\right) 2^{j_i}.
\label{first}
\end{eqnarray}
